def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_c = 0
    my_c = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1
    my_d = n - my_c

    recent = history[-10:]
    rlen = len(recent)
    opp_c_recent = 0
    for a, b in recent:
        if b == 'C':
            opp_c_recent += 1

    if n >= 12:
        if opp_c * 100 < n * 25:
            return 'D'
        if rlen >= 8 and opp_c_recent * 100 < rlen * 15:
            return 'D'

    soft = 0
    hard = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                soft += 1
            else:
                hard += 1

    if last_opp == 'C':
        if opp_c * 100 >= n * 90 and hard == 0 and soft >= 1 and n >= 50 and opp_c_recent >= 9:
            return 'D'
        if opp_c * 100 >= n * 85 and hard == 0 and soft >= 1 and n >= 72 and opp_c_recent >= 8:
            return 'D'
        if opp_c * 100 >= n * 85 and soft > hard and soft >= 2 and n >= 75 and opp_c_recent >= 8:
            return 'D'
        if n >= 90 and opp_c * 100 >= n * 70 and hard == 0 and soft >= 1 and opp_c_recent >= 7:
            return 'D'
        if opp_c * 100 >= n * 95 and my_d == 0 and 60 <= n < 78 and rng.random() < 0.012:
            return 'D'
        if opp_c * 100 >= n * 85 and my_d == 0 and n >= 78:
            return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if opp_c_recent >= 3 or opp_c * 100 >= n * 35:
                if rng.random() < 0.75:
                    return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if opp_c_recent >= 3 or opp_c * 100 >= n * 25:
                return 'C'
            return 'D'

        if opp_c * 100 >= n * 92 and opp_c_recent == rlen and rng.random() < 0.08:
            return 'C'
        return 'D'

    return 'C'
